import json
import logging
import time
from pathlib import Path

from core.database import get_conn

logger = logging.getLogger(__name__)

SOURCES_DIR = Path(__file__).resolve().parent.parent / 'sources'

DYNAMIC_STUB_TEMPLATE = '''# -*- coding: utf-8 -*-
"""Generated by Scraper Generator — DO NOT EDIT manually
Source : {label}
Base URL : {base_url}
Created : {timestamp}
"""

from .dynamic import DynamicSource


class {class_name}(DynamicSource):
    type = '{source_type}'
    label = '{label}'
    CONFIG_NAME = '{config_name}'
'''


def get_all_configs() -> list[dict]:
    conn = get_conn()
    rows = conn.execute(
        'SELECT name, type, label, base_url, built_in, enabled, config_json '
        'FROM scraper_configs ORDER BY built_in DESC, name ASC'
    ).fetchall()
    result = []
    for r in rows:
        cfg = {
            'name': r['name'],
            'type': r['type'],
            'label': r['label'],
            'base_url': r['base_url'],
            'built_in': bool(r['built_in']),
            'enabled': bool(r['enabled']),
        }
        try:
            cfg['config'] = json.loads(r['config_json'])
        except (json.JSONDecodeError, TypeError):
            cfg['config'] = {}
        result.append(cfg)
    return result


def get_config(name: str) -> dict | None:
    conn = get_conn()
    row = conn.execute(
        'SELECT name, type, label, base_url, built_in, enabled, config_json '
        'FROM scraper_configs WHERE name = ?',
        (name,)
    ).fetchone()
    if not row:
        return None
    cfg = {
        'name': row['name'],
        'type': row['type'],
        'label': row['label'],
        'base_url': row['base_url'],
        'built_in': bool(row['built_in']),
        'enabled': bool(row['enabled']),
    }
    try:
        cfg['config'] = json.loads(row['config_json'])
    except (json.JSONDecodeError, TypeError):
        cfg['config'] = {}
    return cfg


def create_config(name: str, source_type: str, label: str,
                  base_url: str, config: dict) -> dict:
    now = time.time()
    conn = get_conn()
    with conn:
        conn.execute(
            'INSERT INTO scraper_configs '
            '(name, type, label, base_url, built_in, enabled, config_json, created_at, updated_at) '
            'VALUES (?, ?, ?, ?, 0, 1, ?, ?, ?)',
            (name, source_type, label, base_url, json.dumps(config), now, now)
        )
    _generate_source_file(name, source_type, label, base_url)
    _register_dynamic(name)
    # Ensure the source is also registered in source_settings so
    # get_enabled_source_names() picks it up right away.
    try:
        from core.database import ensure_source_in_db
        ensure_source_in_db(name, source_type)
    except Exception:
        pass
    logger.info(f"Scraper config created: {name} ({source_type})")
    return get_config(name)


def _reload_dynamic_source(name: str) -> None:
    try:
        from core.sources import SOURCES
        for type_dict in SOURCES.values():
            src = type_dict.get(name)
            if src is not None and hasattr(src, 'reload_config'):
                src.reload_config()
    except Exception:
        pass


def update_config(name: str, label: str | None = None,
                  base_url: str | None = None,
                  enabled: bool | None = None,
                  config: dict | None = None) -> dict | None:
    existing = get_config(name)
    if not existing:
        return None

    now = time.time()
    conn = get_conn()
    with conn:
        if label is not None:
            conn.execute('UPDATE scraper_configs SET label = ? WHERE name = ?', (label, name))
        if base_url is not None:
            conn.execute('UPDATE scraper_configs SET base_url = ? WHERE name = ?', (base_url, name))
        if enabled is not None:
            conn.execute('UPDATE scraper_configs SET enabled = ? WHERE name = ?',
                         (1 if enabled else 0, name))
            try:
                conn.execute('UPDATE source_settings SET enabled = ? WHERE name = ?',
                             (1 if enabled else 0, name))
            except Exception:
                pass
        if config is not None:
            conn.execute('UPDATE scraper_configs SET config_json = ? WHERE name = ?',
                         (json.dumps(config), name))
        if existing['built_in'] and (config is not None or label is not None):
            conn.execute('UPDATE scraper_configs SET built_in = 0 WHERE name = ?', (name,))
        conn.execute('UPDATE scraper_configs SET updated_at = ? WHERE name = ?', (now, name))

    if config is not None or label is not None:
        if existing['built_in']:
            _remove_source_file(name)
        _generate_source_file(
            name, existing['type'], label or existing['label'],
            base_url or existing.get('base_url', ''),
        )
        _register_dynamic(name)

    _reload_dynamic_source(name)
    logger.info(f"Scraper config updated: {name}")
    return get_config(name)


def delete_config(name: str) -> bool:
    existing = get_config(name)
    if not existing or existing['built_in']:
        return False

    conn = get_conn()
    with conn:
        conn.execute('DELETE FROM scraper_configs WHERE name = ?', (name,))

    # Limpiar registros asociados
    _remove_source_file(name)
    _unregister_dynamic(name)
    try:
        from core.database import get_conn as _get_conn
        _get_conn().execute('DELETE FROM source_settings WHERE name = ?', (name,))
    except Exception:
        pass
    try:
        from core.scraper_health import clear_source_health
        clear_source_health(name)
    except Exception:
        pass
    try:
        from core.disk_cache import search_cache
        search_cache.clear()
    except Exception:
        pass
    logger.info(f"Scraper config deleted: {name}")
    return True


def _generate_source_file(name: str, source_type: str, label: str, base_url: str = '') -> None:
    class_name = ''.join(word.capitalize() for word in name.replace('-', '_').split('_')) + 'Source'
    content = DYNAMIC_STUB_TEMPLATE.format(
        class_name=class_name,
        source_type=source_type,
        label=label,
        config_name=name,
        base_url=base_url,
        timestamp=time.strftime('%Y-%m-%d %H:%M:%S'),
    )
    filepath = SOURCES_DIR / f"{name}.py"
    SOURCES_DIR.mkdir(parents=True, exist_ok=True)
    filepath.unlink(missing_ok=True)
    filepath.write_text(content, encoding='utf-8')
    logger.info(f"Generated source file: {filepath}")


def _remove_source_file(name: str) -> None:
    filepath = SOURCES_DIR / f"{name}.py"
    if filepath.exists():
        filepath.unlink()
        logger.info(f"Removed source file: {filepath}")


def _unregister_dynamic(name: str) -> None:
    """Remove a dynamic source from core.sources registries."""
    try:
        from core.sources import SOURCES, ALL_SOURCES_META
        for type_dict in SOURCES.values():
            type_dict.pop(name, None)
        ALL_SOURCES_META[:] = [m for m in ALL_SOURCES_META if m['name'] != name]
    except Exception as exc:
        logger.warning(f"Could not unregister dynamic source {name}: {exc}")


def _register_dynamic(name: str) -> None:
    """Import and register a single dynamic source with core.sources."""
    try:
        from core.sources import register_dynamic_source
        register_dynamic_source(name)
    except Exception as exc:
        logger.warning(f"Could not register dynamic source {name}: {exc}")


def load_dynamic_sources():
    """Import and register all generated source stubs with core.sources."""
    for cfg in get_all_configs():
        if cfg['built_in']:
            continue
        _register_dynamic(cfg['name'])
